import {getSetting,setSetting,putArt,getArt,listArt,pendingArt,artKey} from './storage.mjs';
import {normalizePairCode,PROFILES} from './core.mjs';
export let family='';let busy=false,queued=false,notify=()=>{},onConflict=()=>{};
const COOKIE='little_color_family';
function persistCode(code){localStorage.setItem(COOKIE,code);document.cookie=`${COOKIE}=${code}; Max-Age=31536000; Path=/; SameSite=Strict${location.protocol==='https:'?'; Secure':''}`}
export async function initFamily(status,conflict){notify=status;onConflict=conflict;let code=localStorage.getItem(COOKIE)||document.cookie.split('; ').find(s=>s.startsWith(COOKIE+'='))?.split('=')[1]||await getSetting('family');try{code=normalizePairCode(code||'')}catch{code=Array.from(crypto.getRandomValues(new Uint8Array(32)),v=>v.toString(16).padStart(2,'0')).join('')}family=code;persistCode(code);await setSetting('family',code);window.addEventListener('online',()=>flush());return code}
export async function pairFamily(code){const value=normalizePairCode(code);await request('/api/art?profile=Olivia',{},value);await setSetting('family',value);persistCode(value);family=value;return value}
async function request(path,options={},code=family){const res=await fetch(path,{...options,headers:{Authorization:`Bearer ${code}`,...options.headers},cache:'no-store'});if(!res.ok){const err=new Error(res.status===409?'conflict':'Sync is unavailable');err.status=res.status;throw err}return res.json()}
export function cloudPayload(a){const {id,profile,title,pageId,paint,thumbnail,customBase,updatedAt,revision}=a;return {id,profile,title,pageId,paint,thumbnail,customBase,updatedAt,revision}}
export async function pullList(profile){const target=family,{arts}=await request(`/api/art?profile=${profile}`,{},target);if(target!==family)return [];return arts}
export async function loadRemote(profile,id){const target=family,{art,etag}=await request(`/api/art?profile=${profile}&id=${id}`,{},target);const record={...art,family:target,key:artKey(target,profile,id),etag,pending:false};await putArt(record);return record}
export async function flush(){if(busy){queued=true;return}if(!navigator.onLine){notify('offline');return}busy=true;queued=false;const target=family;try{const pending=await pendingArt(target);if(!pending.length){notify('synced');return}notify('syncing');for(const a of pending){try{const {etag}=await request(`/api/art?profile=${a.profile}&id=${a.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({art:cloudPayload(a),etag:a.etag||null})},target);const latest=await getArt(a.key);if(!latest)continue;if(latest.revision===a.revision){latest.etag=etag;latest.pending=false;await putArt(latest)}else{latest.etag=etag;await putArt(latest);queued=true}}catch(e){if(e.status!==409)throw e;const latest=await getArt(a.key);const id=crypto.randomUUID(),fork={...latest,id,key:artKey(target,a.profile,id),title:(latest.title+' · another version').slice(0,100),etag:null,pending:true};await putArt(fork);await loadRemote(a.profile,a.id);onConflict(a.id,fork);queued=true}}notify(queued?'syncing':'synced')}catch{notify(navigator.onLine?'waiting':'offline')}finally{busy=false;if(queued&&family===target)setTimeout(()=>flush(),1000)}}
export async function mergeGallery(profile){const target=family,local=await listArt(target,profile);let remote=[];try{remote=await pullList(profile);notify('synced')}catch{notify(navigator.onLine?'waiting':'offline')}if(target!==family)return [];const map=new Map(local.map(a=>[a.id,a]));for(const a of remote){const localArt=map.get(a.id);if(!localArt||(!localArt.pending&&a.etag!==localArt.etag))map.set(a.id,{...a,remote:true})}return [...map.values()].sort((a,b)=>b.updatedAt-a.updatedAt)}
export async function syncProfile(profile){if(!PROFILES.includes(profile))return;await flush();return mergeGallery(profile)}
